cypress_script:
describe('Contact Form Validation', () => {
  it('should submit the form with valid inputs', () => {
    cy.visit('https://practicesoftwaretesting.com/contact');
    cy.get('#first_name').type('John');
    cy.get('#last_name').type('Doe');
    cy.get('#email').type('john.doe@example.com');
    cy.get('#subject').select('customer-service');
    cy.get('#message').type('Hello, I have a question.');
    cy.get('[data-test="contact-submit"]').click();
    cy.url().should('not.include', '/contact');
  });

  it('should not submit the form if required fields are empty', () => {
    cy.visit('https://practicesoftwaretesting.com/contact');
    cy.get('[data-test="contact-submit"]').click();
    cy.url().should('include', '/contact');
    cy.get('h1').should('have.text', 'Contact');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Contact Form Validation', () => {
  test('should submit the form with valid inputs', async ({ page }) => {
    await page.goto('https://practicesoftwaretesting.com/contact');
    await page.fill('#first_name', 'John');
    await page.fill('#last_name', 'Doe');
    await page.fill('#email', 'john.doe@example.com');
    await page.selectOption('#subject', 'customer-service');
    await page.fill('#message', 'Hello, I have a question.');
    await page.click('[data-test="contact-submit"]');
    await expect(page).toHaveURL(/^(?!.*contact).*/);
  });

  test('should not submit the form if required fields are empty', async ({ page }) => {
    await page.goto('https://practicesoftwaretesting.com/contact');
    await page.click('[data-test="contact-submit"]');
    await expect(page).toHaveURL(/contact/);
    const heading = page.locator('h1');
    await expect(heading).toHaveText('Contact');
  });
});
